# classify each action by how bad a mistake would be
RISK = {
    "read_file":      "low",     # trivially reversible / harmless
    "send_email":     "high",    # can't unsend
    "delete_records": "high",    # destructive
    "issue_refund":   "high",    # moves real money
}

def needs_approval(action: str) -> bool:
    return RISK.get(action, "high") == "high"  # unknown -> treat as risky

print(needs_approval("send_email"))   # True: gate it

IRREVERSIBLE = {"issue_refund", "delete_records", "send_email", "deploy"}

def gate_decision(action: str, amount: float = 0) -> str:
    if action in IRREVERSIBLE:
        return "approve"           # human must confirm
    if amount > 100:               # even reversible-but-costly actions
        return "approve"
    return "auto"                  # safe to run without a human

print(gate_decision("issue_refund"))       # approve
print(gate_decision("update_draft", 5))     # auto

def step_with_gate(action, args, reason):
    if needs_approval(action):
        req_id = propose(action, args, reason)
        return {"paused": True, "await": req_id}   # yield control, no blocking
    return {"paused": False, "result": run_tool(action, args)}

def resume(req_id: int):
    item = queue[req_id]
    if item["status"] == "approved":
        return run_tool(item["action"], item["args"])
    return {"replan": f"denied: {item.get('note','')}"}  # let the agent adapt

def route(action: str, amount: float, trusted: bool) -> str:
    if trusted and amount <= 25:
        return "auto"              # pre-approved, low-value -> no human
    if action in IRREVERSIBLE or amount > 500:
        return "approve"           # clearly needs a human
    return "auto"

# thresholds keep the queue small enough that humans actually read it
print(route("issue_refund", 12, trusted=True))   # auto
print(route("issue_refund", 800, trusted=True))  # approve

