IRREVERSIBLE = {"issue_refund", "send_email", "delete_records", "deploy"}

def route(action: str, amount: float = 0.0, trusted: bool = False) -> str:
    if trusted and amount <= 25:
        return "auto"                     # pre-approved low-value case
    if action in IRREVERSIBLE or amount > 100:
        return "approve"                  # needs a human
    return "auto"                         # reversible & cheap -> autonomous

cases = [
    ("read_file", 0, False),
    ("issue_refund", 40, False),
    ("issue_refund", 12, True),
    ("update_draft", 5, False),
]
for action, amt, trusted in cases:
    print(action, "->", route(action, amt, trusted))

queue = []
IRREVERSIBLE = {"issue_refund", "send_email"}

def run_tool(action, args):
    return f"EXECUTED {action} {args}"

def step(action, args, reason):
    if action in IRREVERSIBLE:
        item = {"id": len(queue), "action": action, "args": args,
                "reason": reason, "status": "pending", "note": ""}
        queue.append(item)
        return {"paused": True, "await": item["id"]}   # no execution yet
    return {"paused": False, "result": run_tool(action, args)}

def decide(req_id, approved, note=""):
    queue[req_id]["status"] = "approved" if approved else "denied"
    queue[req_id]["note"] = note

def resume(req_id):
    item = queue[req_id]
    if item["status"] == "approved":
        return run_tool(item["action"], item["args"])
    return {"replan": f"denied: {item['note']}"}

out = step("issue_refund", {"order": "A-9", "usd": 40}, "double charge")
print("paused, awaiting", out["await"])
decide(out["await"], approved=True, note="verified in billing")
print(resume(out["await"]))

