def step(action, args):
    if action in IRREVERSIBLE:
        propose(action, args)      # enqueue the request
    return run_tool(action, args)  # ...but run it anyway, every time

IRREVERSIBLE = {"refund", "send"}
def route(a, amt):
    if a in IRREVERSIBLE or amt > 100:
        return "approve"
    return "auto"
print(route("read", 500))
